function subsequenceCount(nums) {
  const MOD = 1000000007;
  const hasOdd = nums.some(value => value % 2 === 1);
  if (!hasOdd) {
    return 0;
  }
  let count = 1;
  for (let i = 1; i < nums.length; i++) {
    count = (count * 2) % MOD;
  }
  return count;
}

