function subsequenceCount(nums) {
  // Track how many subsequences so far have an even sum (the empty one included) and how many an odd sum.
  const MOD = 1000000007;
  let even = 1, odd = 0;
  for (const value of nums) {
    if (value % 2 === 0) {
      even = (even * 2) % MOD;
      odd = (odd * 2) % MOD;
    } else {
      const total = (even + odd) % MOD;
      even = total;
      odd = total;
    }
  }
  return odd;
}

