function generate(rand, size) {
  const n = size === 'large' ? 1000 + Math.floor(rand() * 1001) : 1 + Math.floor(rand() * 10);
  const top = size === 'large' ? 1000000000 : 12;
  const mode = rand();
  // A quarter of the inputs are all even (no odd sum at all); another quarter have only a few odd values.
  const oddChance = mode < 0.25 ? 0 : mode < 0.5 ? 0.1 : 0.5;
  return [Array.from({ length: n }, () => {
    const half = Math.floor(rand() * (top / 2));
    return rand() < oddChance ? 2 * half + 1 : 2 * half + 2;
  })];
}
